def prime_square_sum(count: int, modulus: int) -> int:

    total: int = 0
    found: int = 0
    n: int = 2
    while found < count:
        if is_probable_prime(n):
            total = (total + n * n) % modulus
            found += 1
        n += 1
    return total


def is_probable_prime(n: int) -> bool:

    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    d: int = 5
    while d * d <= n:
        if n % d == 0 or n % (d + 2) == 0:
            return False
        d += 6
    return True

